def parse_bool_expr(expression: str) -> bool:
    stack = []
    for ch in expression:
        if ch == ",":
            continue
        if ch != ")":
            stack.append(ch)
            continue
        # Collect operands of the innermost open operator.
        seen_true = seen_false = False
        while stack[-1] != "(":
            if stack.pop() == "t":
                seen_true = True
            else:
                seen_false = True
        stack.pop()           # the '('
        op = stack.pop()
        if op == "!":
            value = seen_false        # exactly one operand: NOT flips it
        elif op == "&":
            value = not seen_false
        else:
            value = seen_true
        stack.append("t" if value else "f")
    return stack[-1] == "t"

def minimum_size(nums: List[int], max_operations: int) -> int:
    def operations_needed(penalty: int) -> int:
        # A bag of x balls needs (x - 1) // penalty splits.
        return sum((x - 1) // penalty for x in nums)

    lo, hi = 1, max(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if operations_needed(mid) <= max_operations:
            hi = mid          # feasible: try a smaller penalty
        else:
            lo = mid + 1
    return lo

