def max_number_of_alloys(n: int, k: int, budget: int, composition: List[List[int]],
                         stock: List[int], cost: List[int]) -> int:
    upper = min(stock) + budget
    best = 0
    for need in composition:
        def affordable(x: int) -> bool:
            spent = 0
            for j in range(n):
                short = x * need[j] - stock[j]
                if short > 0:
                    spent += short * cost[j]
                    if spent > budget:
                        return False
            return True

        # Largest x in [best, upper] this machine can afford.
        if not affordable(best + 1):
            continue
        lo, hi = best + 1, upper
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if affordable(mid):
                lo = mid
            else:
                hi = mid - 1
        best = lo
    return best

