def find_repeated_dna_sequences(s: str) -> list[str]:
    L = 10
    if len(s) <= L:
        return []
    code = {"A": 0, "C": 1, "G": 2, "T": 3}
    mask = (1 << (2 * L)) - 1
    seen, reported = set(), set()
    result = []
    window = 0
    for i, ch in enumerate(s):
        # Roll the 20 bit window forward by one letter.
        window = ((window << 2) | code[ch]) & mask
        if i < L - 1:
            continue
        if window in seen:
            if window not in reported:
                reported.add(window)
                result.append(s[i - L + 1:i + 1])
        else:
            seen.add(window)
    return result

