def nearest_palindromic(n: str) -> str:
    length = len(n)
    value = int(n)
    # Palindromes with one digit fewer (all nines) or one digit more (10...01).
    candidates = {10 ** (length - 1) - 1, 10 ** length + 1}
    prefix = int(n[:(length + 1) // 2])
    for p in (prefix - 1, prefix, prefix + 1):
        left = str(p)
        if length % 2 == 0:
            pal = left + left[::-1]
        else:
            pal = left + left[:-1][::-1]   # the middle digit is not repeated
        candidates.add(int(pal))
    candidates.discard(value)
    best = min(candidates, key=lambda c: (abs(c - value), c))
    return str(best)

def find_min_height_trees(n: int, edges: list[list[int]]) -> list[int]:
    if n <= 2:
        return list(range(n))
    adj = [[] for _ in range(n)]
    degree = [0] * n
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
        degree[a] += 1
        degree[b] += 1
    leaves = [v for v in range(n) if degree[v] == 1]
    remaining = n
    # Strip leaves layer by layer until only the centre is left.
    while remaining > 2:
        remaining -= len(leaves)
        next_leaves = []
        for leaf in leaves:
            for nb in adj[leaf]:
                degree[nb] -= 1
                if degree[nb] == 1:
                    next_leaves.append(nb)
        leaves = next_leaves
    return leaves

def predict_the_winner(nums: list[int]) -> bool:
    n = len(nums)
    # dp[j] = best lead the player to move can force on nums[i..j].
    dp = nums[:]
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            take_left = nums[i] - dp[j]        # dp[j] is still the value for i+1..j
            take_right = nums[j] - dp[j - 1]   # dp[j-1] already holds i..j-1
            dp[j] = max(take_left, take_right)
    return dp[n - 1] >= 0

