def count_good_subsequences(s: str) -> int:
    MOD = 10 ** 9 + 7
    counts = list(Counter(s).values())
    n = len(s)
    # Factorials and inverse factorials for O(1) binomial coefficients.
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(a: int, b: int) -> int:
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    total = 0
    for f in range(1, max(counts) + 1):
        ways = 1
        for c in counts:
            if c >= f:
                ways = ways * (comb(c, f) + 1) % MOD   # skip the letter, or pick f of its c spots
        total = (total + ways - 1) % MOD             # drop the all skipped (empty) choice
    return total

