                search(j, expr + "-" + part, value - x, -x)
                # Undo the last term, then apply the product to it alone.
                search(j, expr + "*" + part, value - last + last * x, last * x)

    search(0, "", 0, 0)
    return results

def find_diagonal_order(nums: list[list[int]]) -> list[int]:
    buckets = []
    for i, row in enumerate(nums):
        for j, value in enumerate(row):
            d = i + j
            while len(buckets) <= d:
                buckets.append([])
            buckets[d].append(value)     # rows arrive top to bottom
    result = []
    for bucket in buckets:
        result.extend(reversed(bucket))  # bottom left to top right
    return result

def number_of_steps(num: int) -> int:
    if num == 0:
        return 0
    # One subtraction per 1 bit, one halving per bit except the leading one.
    return num.bit_length() + bin(num).count("1") - 1

def min_falling_path_sum(matrix: list[list[int]]) -> int:
    n = len(matrix)
    prev = list(matrix[0])  # best path sum ending at each column of the previous row
    for r in range(1, n):
        row = matrix[r]
        cur = [0] * n
        for c in range(n):
            best = prev[c]
            if c > 0 and prev[c - 1] < best:
                best = prev[c - 1]
            if c + 1 < n and prev[c + 1] < best:
                best = prev[c + 1]
            cur[c] = row[c] + best
        prev = cur
    return min(prev)

