def maximum_detonation(bombs: list[list[int]]) -> int:
    n = len(bombs)
    # reach[i] lists the bombs inside bomb i's blast circle.
    reach = [[] for _ in range(n)]
    for i in range(n):
        xi, yi, ri = bombs[i]
        r2 = ri * ri
        for j in range(n):
            if i != j:
                dx = xi - bombs[j][0]
                dy = yi - bombs[j][1]
                if dx * dx + dy * dy <= r2:
                    reach[i].append(j)
    best = 0
    for start in range(n):
        seen = [False] * n
        seen[start] = True
        stack = [start]
        count = 1
        while stack:
            u = stack.pop()
            for v in reach[u]:
                if not seen[v]:
                    seen[v] = True
                    count += 1
                    stack.append(v)
        best = max(best, count)
        if best == n:
            break
    return best

