def merge_trees(root1: Optional[TreeNode], root2: Optional[TreeNode]) -> Optional[TreeNode]:
    if root1 is None:
        return root2
    if root2 is None:
        return root1
    stack = [(root1, root2)]  # pairs where both trees have a node
    while stack:
        a, b = stack.pop()
        a.val += b.val
        if a.left is None:
            a.left = b.left          # only the second tree continues here
        elif b.left is not None:
            stack.append((a.left, b.left))
        if a.right is None:
            a.right = b.right
        elif b.right is not None:
            stack.append((a.right, b.right))
    return root1

def spellchecker(wordlist: list[str], queries: list[str]) -> list[str]:
    vowels = str.maketrans("aeiou", "*****")

    def mask(word):
        # Lowercase, then hide which vowel sits in each vowel position.
        return word.lower().translate(vowels)

    exact = set(wordlist)
    by_case = {}
    by_vowel = {}
    for w in wordlist:
        by_case.setdefault(w.lower(), w)   # earliest word wins
        by_vowel.setdefault(mask(w), w)

    out = []
    for q in queries:
        if q in exact:
            out.append(q)
        elif q.lower() in by_case:
            out.append(by_case[q.lower()])
        else:
            out.append(by_vowel.get(mask(q), ""))
    return out

