def nearest_exit(maze: list[list[str]], entrance: list[int]) -> int:
    m, n = len(maze), len(maze[0])
    sr, sc = entrance
    seen = [[False] * n for _ in range(m)]
    seen[sr][sc] = True
    queue = deque([(sr, sc, 0)])
    while queue:
        r, c, d = queue.popleft()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < m and 0 <= nc < n and not seen[nr][nc] and maze[nr][nc] == ".":
                # Any open boundary cell other than the entrance is an exit.
                if nr == 0 or nr == m - 1 or nc == 0 or nc == n - 1:
                    return d + 1
                seen[nr][nc] = True
                queue.append((nr, nc, d + 1))
    return -1

