def min_cost(n: int, roads: list[list[int]], apple_cost: list[int], k: int) -> list[int]:
    graph = [[] for _ in range(n)]
    factor = k + 1  # a road is paid once going and k times returning
    for a, b, cost in roads:
        graph[a - 1].append((b - 1, cost * factor))
        graph[b - 1].append((a - 1, cost * factor))
    best = list(apple_cost)  # buying at home is always an option
    heap = [(c, city) for city, c in enumerate(apple_cost)]
    heapq.heapify(heap)
    while heap:
        d, u = heapq.heappop(heap)
        if d > best[u]:
            continue  # stale entry
        for v, w in graph[u]:
            nd = d + w
            if nd < best[v]:
                best[v] = nd
                heapq.heappush(heap, (nd, v))
    return best

def max_xor(n: int, edges: list[list[int]], values: list[int]) -> int:
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    # Parent pointers and a DFS order, then subtree sums bottom up.
    parent = [-1] * n
    order = [0]
    parent[0] = 0
    for u in order:
        for v in adj[u]:
            if parent[v] == -1:
                parent[v] = u
                order.append(v)
    total = list(values)
    for u in reversed(order[1:]):
        total[parent[u]] += total[u]
    bits = max(total).bit_length()

    # Binary trie stored in parallel arrays; node 0 is the root.
    zero, one = [0], [0]

    def insert(x):
        node = 0
        for b in range(bits - 1, -1, -1):
            child = one if (x >> b) & 1 else zero
            if child[node] == 0:
                zero.append(0); one.append(0)
                child[node] = len(zero) - 1
            node = child[node]

    def query(x):
        node, res = 0, 0
        for b in range(bits - 1, -1, -1):
            if (x >> b) & 1:
                want, other = zero, one
            else:
                want, other = one, zero
            if want[node]:
                res |= 1 << b
                node = want[node]
            else:
                node = other[node]
        return res

    best = 0
    stack = [(0, False)]
    count = 0  # number of finished subtrees in the trie
    while stack:
        u, leaving = stack.pop()
        if leaving:
            insert(total[u])  # u's subtree is now complete and disjoint from later nodes
            count += 1
            continue
        if count:
            best = max(best, query(total[u]))
        stack.append((u, True))
        for v in adj[u]:
            if v != 0 and parent[v] == u:  # children only
                stack.append((v, False))
    return best

def minimum_semesters(n: int, relations: list[list[int]]) -> int:
    graph = [[] for _ in range(n + 1)]
    indeg = [0] * (n + 1)
    for prev, nxt in relations:
        graph[prev].append(nxt)
        indeg[nxt] += 1
    ready = [c for c in range(1, n + 1) if indeg[c] == 0]
    semesters, taken = 0, 0
    while ready:
        semesters += 1
        taken += len(ready)
        nxt_ready = []
        for c in ready:
            for d in graph[c]:
                indeg[d] -= 1
                if indeg[d] == 0:
                    nxt_ready.append(d)
        ready = nxt_ready
    return semesters if taken == n else -1

def find_disappeared_numbers(nums: list[int]) -> list[int]:
    for v in nums:
        slot = abs(v) - 1
        if nums[slot] > 0:
            nums[slot] = -nums[slot]  # mark value slot + 1 as present
    missing = [i + 1 for i, v in enumerate(nums) if v > 0]
    for i in range(len(nums)):
        nums[i] = abs(nums[i])  # restore the input
    return missing

